CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE app_users ADD CONSTRAINT rota_account_roles CHECK(role IN ('owner','manager','staff'));
CREATE TABLE workspaces(id uuid PRIMARY KEY,owner_id uuid NOT NULL UNIQUE REFERENCES app_users(id));
CREATE TABLE workspace_members(workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id uuid NOT NULL REFERENCES app_users(id),role text NOT NULL CHECK(role IN ('owner','manager','staff')),PRIMARY KEY(workspace_id,user_id),UNIQUE(user_id));
CREATE TABLE locations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 80),timezone text NOT NULL,UNIQUE(workspace_id,id));
CREATE TABLE positions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 80),UNIQUE(workspace_id,name),UNIQUE(workspace_id,id));
CREATE TABLE shift_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL CHECK(length(name) BETWEEN 1 AND 80),UNIQUE(workspace_id,name),UNIQUE(workspace_id,id));
CREATE TABLE staff(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),email text NOT NULL,name text NOT NULL CHECK(length(name) BETWEEN 1 AND 120),user_id uuid REFERENCES app_users(id),UNIQUE(workspace_id,email),UNIQUE(workspace_id,id),UNIQUE(workspace_id,user_id));
CREATE TABLE rota_weeks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),starts_on date NOT NULL CHECK(extract(isodow from starts_on)=1),state text NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','published')),UNIQUE(workspace_id,starts_on),UNIQUE(workspace_id,id));
CREATE TABLE shifts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,week_id uuid NOT NULL,location_id uuid NOT NULL,position_id uuid NOT NULL,type_id uuid NOT NULL,assignee_id uuid,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,CHECK(ends_at>starts_at AND ends_at-starts_at<=interval '24 hours'),FOREIGN KEY(workspace_id,week_id) REFERENCES rota_weeks(workspace_id,id),FOREIGN KEY(workspace_id,location_id) REFERENCES locations(workspace_id,id),FOREIGN KEY(workspace_id,position_id) REFERENCES positions(workspace_id,id),FOREIGN KEY(workspace_id,type_id) REFERENCES shift_types(workspace_id,id),FOREIGN KEY(workspace_id,assignee_id) REFERENCES staff(workspace_id,id),UNIQUE(workspace_id,id),EXCLUDE USING gist (assignee_id WITH =,tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE (assignee_id IS NOT NULL));
CREATE TABLE availability(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,staff_id uuid NOT NULL,weekday integer CHECK(weekday BETWEEN 1 AND 7),starts_at time,ends_at time,unavailable_on date,FOREIGN KEY(workspace_id,staff_id) REFERENCES staff(workspace_id,id),CHECK((unavailable_on IS NOT NULL AND weekday IS NULL AND starts_at IS NULL AND ends_at IS NULL) OR (unavailable_on IS NULL AND weekday IS NOT NULL AND starts_at IS NOT NULL AND ends_at>starts_at)));
CREATE TABLE time_off(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,staff_id uuid NOT NULL,starts_on date NOT NULL,ends_on date NOT NULL CHECK(ends_on>=starts_on),reason text NOT NULL DEFAULT '' CHECK(length(reason)<=1000),state text NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','approved','declined')),FOREIGN KEY(workspace_id,staff_id) REFERENCES staff(workspace_id,id));
CREATE TABLE swaps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL,shift_id uuid NOT NULL,from_staff uuid NOT NULL,to_staff uuid,state text NOT NULL DEFAULT 'offered' CHECK(state IN ('offered','taken','approved','declined')),FOREIGN KEY(workspace_id,shift_id) REFERENCES shifts(workspace_id,id),FOREIGN KEY(workspace_id,from_staff) REFERENCES staff(workspace_id,id),FOREIGN KEY(workspace_id,to_staff) REFERENCES staff(workspace_id,id),CHECK(to_staff IS NULL OR to_staff<>from_staff));
CREATE UNIQUE INDEX one_active_swap ON swaps(shift_id) WHERE state IN ('offered','taken');
CREATE TABLE rota_invites(id uuid PRIMARY KEY,token_hash text NOT NULL UNIQUE,email text NOT NULL,workspace_id uuid NOT NULL REFERENCES workspaces(id),role text NOT NULL CHECK(role IN ('manager','staff')),invited_by uuid NOT NULL REFERENCES app_users(id),emailed boolean NOT NULL DEFAULT false,expires_at timestamptz NOT NULL,used_at timestamptz);
CREATE UNIQUE INDEX rota_invites_active ON rota_invites(workspace_id,email) WHERE used_at IS NULL;
CREATE INDEX shifts_week ON shifts(workspace_id,week_id);
